INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-decoy-wood', 'south', 'the-hard-lane', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hard-lane', 'door', 'The Hard Lane', 'The track up off the marsh onto the hard ground, cut down by feet and carts until it runs a body''s depth below the turf on either hand, with salt crusted white along the foot of both banks. Walking it you see nothing but sky and the two walls of earth, and nothing can see you.', 0, 0, 'crossing', 0, 59, 15, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard-lane', 'north', 'the-decoy-wood', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard-lane', 'south', 'the-row-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard-lane', 'east', 'the-pump-green', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pump-green', 'door', 'The Pump Green', 'A shelf of short salt-bitten grass with the hamlet''s well in the middle of it, a stone ring capped with a slab somebody dragged on and left crooked. The water under the slab is sweet, which out here was worth building a village round, and the bucket rope has rotted off at the windlass.', 0, 0, 'crossing', 0, 60, 15, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pump-green', 'west', 'the-hard-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pump-green', 'south', 'the-salt-pound', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sea-furrows', 'door', 'The Sea Furrows', 'The ground runs in long parallel waves, a stride from crest to crest, ploughed for a few hundred years on the one patch of hard land the sea left alone. The crests are bleached and the hollows hold water after rain, and the wind comes off the marsh across the top of them without anything to stop it.', 0, 0, 'crossing', 0, 58, 16, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sea-furrows', 'east', 'the-row-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sea-furrows', 'south', 'the-marsh-field', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-row-foot', 'door', 'The Row Foot', 'Where the furrows stop and the houses start. There is no boundary except that the grass gives way to a hard rutted surface of shell and grit and the first walls stand up beside you. Somebody lit a fire against a gable end here and put it out badly, and the scorch is still black.', 0, 0, 'crossing', 0, 59, 16, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-row-foot', 'west', 'the-sea-furrows', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-row-foot', 'north', 'the-hard-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-row-foot', 'south', 'the-salters-row', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-row-foot', 'east', 'the-salt-pound', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-salt-pound', 'door', 'The Salt Pound', 'A round stone pen with a gate that still swings, built to hold stock found straying on the marsh until their owner paid to have them back. It is dry-laid and four courses high and in better repair than anything with a roof on it. Whatever was last shut in here got out over the top.', 0, 0, 'crossing', 0, 60, 16, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-pound', 'west', 'the-row-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-pound', 'north', 'the-pump-green', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-marsh-field', 'door', 'The Marsh Field', 'The big field, open, no hedge in it, worked in strips by everybody at once and grazed by everybody''s sheep after harvest. It has been neither since. What is left is a wide flat meadow that goes grey-green in a wind off the sea, and the geese come down onto it in the evening because nothing here objects.', 0, 0, 'crossing', 0, 58, 17, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-field', 'north', 'the-sea-furrows', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-field', 'east', 'the-salters-row', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-field', 'south', 'the-yard-backs', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-salters-row', 'door', 'The Salters'' Row', 'The one street, wide enough for two carts, with the cots standing back off it behind their own low walls. The surface is laid shell where somebody laid it and mud where nobody did. Every door in sight is shut, and that is the thing you notice and then cannot stop noticing: they were shut on the way out, by people who expected to want them shut.', 0, 0, 'crossing', 0, 59, 17, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salters-row', 'north', 'the-row-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salters-row', 'west', 'the-marsh-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salters-row', 'south', 'the-salt-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salters-row', 'east', 'the-smiths-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-smiths-yard', 'door', 'The Smith''s Yard', 'A yard black underfoot with hammer-scale trodden into it, and it will never grow anything again. A stone trough stands at the wall, cracked through and white with salt where the water dried, and the iron smell still comes up out of the ground when the sea fret gets into it.', 0, 0, 'crossing', 0, 60, 17, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-smiths-yard', 'west', 'the-salters-row', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-smiths-yard', 'east', 'the-sea-smithy', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-smiths-yard', 'south', 'the-saltmasters-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sea-smithy', 'door', 'The Sea Smithy', 'Inside, the roof holds and the light comes through the door and one small window. The hearth is a stone box with a hood over it, the anvil block is still bolted down though the anvil went with somebody, and there is a wall of hooks with nothing on them, every one of them rusted thick by the salt air.', 0, 0, 'crossing', 0, 61, 17, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sea-smithy', 'west', 'the-smiths-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-yard-backs', 'door', 'The Yard Backs', 'Behind the cots, the long thin gardens that came with them, each walled off from the next and all of them gone to sea-kale and nettle and a few wind-bent elder still flowering out of habit. There are gaps worn into the back walls where people took the short way to the field.', 0, 0, 'crossing', 0, 58, 18, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-yard-backs', 'north', 'the-marsh-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-yard-backs', 'east', 'the-salt-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-yard-backs', 'south', 'the-chapel-hard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-salt-cross', 'door', 'The Salt Cross', 'The middle of the place: a stone cross on three steps, the head broken off level and the stump worn round by weather off the sea. People met here and were told things here, and the steps are dished where they sat. Somebody scratched a tally into the bottom step, a great many strokes, and then stopped.', 0, 0, 'crossing', 0, 59, 18, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-cross', 'north', 'the-salters-row', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-cross', 'west', 'the-yard-backs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-cross', 'south', 'the-row-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-cross', 'east', 'the-saltmasters-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-saltmasters-yard', 'door', 'The Saltmaster''s Yard', 'The biggest yard on the row, cobbled, with a boiling-house on one side that has lost half its roof and a house on the other that has lost none of its. The saltmaster answered for everybody else''s pans to whoever owned the marsh, which made him neither one thing nor the other, and he got a better house for it.', 0, 0, 'crossing', 0, 60, 18, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltmasters-yard', 'west', 'the-salt-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltmasters-yard', 'north', 'the-smiths-yard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltmasters-yard', 'east', 'the-saltmasters-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltmasters-yard', 'south', 'the-far-cot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-saltmasters-house', 'door', 'The Saltmaster''s House', 'Two rooms and a floor above, which was wealth here. The hearth is a proper one against a stone gable, with a lintel and a hook still in it. There is a bench built into the wall, a bedstead frame with nothing on it, and a shuttered window that still shuts. Somebody swept this floor before they left it.', 0, 0, 'crossing', 0, 61, 18, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltmasters-house', 'west', 'the-saltmasters-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-burnt-cot', 'door', 'The Burnt Cot', 'One cot did burn, and only one, a long time before the rest of it emptied. The walls stand to shoulder height with the fire''s black still on the inside face, and a thorn has grown up through where the hearth was. Nobody built here again, and whatever the story was, everybody who knew it agreed about it.', 0, 0, 'crossing', 0, 57, 19, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burnt-cot', 'east', 'the-chapel-hard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burnt-cot', 'south', 'the-wind-orchard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-chapel-hard', 'door', 'The Chapel Hard', 'A patch of level laid stone in front of the chapel, kept clear of graves and used for everything else, worn bare in the middle by whatever it was used for. Two yews stand on it, both enormous and both bent landward by the wind, older than the chapel and standing where yews always stand.', 0, 0, 'crossing', 0, 58, 19, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-hard', 'west', 'the-burnt-cot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-hard', 'north', 'the-yard-backs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-hard', 'east', 'the-row-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-hard', 'south', 'the-salt-chapel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-row-head', 'door', 'The Row Head', 'The street ends at a gate in a wall, and past the gate the ground goes on south toward the far waste. From here you can see the whole place at once, back up the length of it to the marsh, and count the roofs, and see that they are all still on.', 0, 0, 'crossing', 0, 59, 19, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-row-head', 'north', 'the-salt-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-row-head', 'west', 'the-chapel-hard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-row-head', 'east', 'the-far-cot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-row-head', 'south', 'the-net-green', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-far-cot', 'door', 'The Far Cot', 'The last yard before the wall, and the poorest: a cot with a byre built onto the end of it under the same roof, so the family and the cow lived a partition apart and kept each other warm. The muck channel still runs out through the wall and away toward the marsh.', 0, 0, 'crossing', 0, 60, 19, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-cot', 'west', 'the-row-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-cot', 'north', 'the-saltmasters-yard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-cot', 'east', 'the-far-house', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-far-house', 'door', 'The Far House', 'One room, and the byre through the gap where a partition was. The floor is beaten earth with a hearth-stone set in the middle and no chimney at all. The smoke went up through the thatch, and the underside of the thatch is black with it and hard as a shell, and that is what has kept the rain out this long.', 0, 0, 'crossing', 0, 61, 19, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-house', 'west', 'the-far-cot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-salt-chapel', 'door', 'The Salt Chapel', 'Stone, and small, and the roof is stone too, the only stone roof for a long way, which is why it is the one building here that will certainly still be standing in another hundred years. Everything that could be carried was carried out. What is left is a font cut from a single block, a stone bench along the wall, and a door that shuts on the world and is thick enough to mean it.', 0, 1, 'crossing', 0, 58, 20, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-chapel', 'north', 'the-chapel-hard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-wind-orchard', 'door', 'The Wind Orchard', 'The chapel''s orchard, every tree in it leaning the same way off the sea, and half of it standing dead with the bark coming off in sheets while the other half goes on fruiting out of the same soil for no reason anyone could explain. Windfalls rot in the grass under the living half every year, and something comes for them every night.', 0, 0, 'crossing', 0, 57, 20, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-orchard', 'north', 'the-burnt-cot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-net-green', 'door', 'The Net Green', 'Level ground with lines of low posts across it, and between the posts nothing now but the weather. Nets were hung here to mend and hides were pegged out here, side by side, because the ground was common and nobody could stop either. The grass under the old lines is a different green from the rest.', 0, 0, 'crossing', 0, 59, 20, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-net-green', 'north', 'the-row-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-net-green', 'east', 'the-bare-toft', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-net-green', 'south', 'the-dipping-well', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-bare-toft', 'door', 'The Bare Toft', 'A house-sized rectangle of levelled ground with a low bank round it, and inside the bank not one stone standing. The walls went to somebody else''s walls and the roof went for firewood, and what is left is the shape of a home printed on the ground. There is a doorstep, still, worn hollow.', 0, 0, 'crossing', 0, 60, 20, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-toft', 'west', 'the-net-green', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-toft', 'east', 'the-sallow-rows', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-toft', 'south', 'the-strand-graves', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sallow-rows', 'door', 'The Sallow Rows', 'Willow grown as a crop in the wet ground, cut to the stool every year for the long rods that made baskets and eel-traps and lobster pots. Nobody has cut these in decades, so each stool has become a small mad tree of its own, forty trunks out of one root, and the rows are still straight underneath.', 0, 0, 'crossing', 0, 61, 20, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sallow-rows', 'west', 'the-bare-toft', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sallow-rows', 'south', 'the-marsh-end', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-turf-hut', 'door', 'The Turf Hut', 'Turf walls two feet thick, a roof of turf on bent driftwood, no window, and a door you go through bent double. Inside it is black, smoke-black floor to roof, from a fire that had no chimney and did not need one. It is bone dry and warm the moment you are out of the wind, and there is old bracken bedding along one wall.', 0, 0, 'crossing', 0, 58, 21, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turf-hut', 'east', 'the-dipping-well', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dipping-well', 'door', 'The Dipping Well', 'Not a well so much as a hole with a barrel sunk in it, where the sweet water sits close under the turf on top of the salt. The barrel staves are still sound and the water inside is clear and about three feet down and full of the sky. There is a hoof-print in the mud on every side of it.', 0, 0, 'crossing', 0, 59, 21, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dipping-well', 'north', 'the-net-green', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dipping-well', 'west', 'the-turf-hut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dipping-well', 'east', 'the-strand-graves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dipping-well', 'south', 'the-old-hearths', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-strand-graves', 'door', 'The Strand Graves', 'Twenty-odd low mounds in rows, unmarked except by the sea-pinks growing thicker over them, on ground outside every boundary there was. When something went through here quickly they buried the dead quickly and away from everyone, which is what this is. It is a tidier piece of ground than anything else on the hard.', 0, 0, 'crossing', 0, 60, 21, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-graves', 'west', 'the-dipping-well', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-graves', 'north', 'the-bare-toft', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-graves', 'east', 'the-marsh-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-graves', 'south', 'the-gorse-corner', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-marsh-end', 'door', 'The Marsh End', 'The hard ground gives out eastward into creek and sedge and standing water with no way through that a person would choose. You can see a long way over the top of it and there is nothing to see: more of the same, going on until it meets the sea.', 0, 0, 'crossing', 0, 61, 21, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-end', 'west', 'the-strand-graves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-end', 'north', 'the-sallow-rows', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-old-hearths', 'door', 'The Old Hearths', 'A ring of flat stones set in the turf, black with fire, and round them the low marks of shelters that were put up and taken down here season after season. Somebody cooked for a lot of people at once here, for a long time, and the stones are still the warmest thing on the ground at the end of a sunny day.', 0, 0, 'crossing', 0, 59, 22, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-hearths', 'north', 'the-dipping-well', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-hearths', 'east', 'the-gorse-corner', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-gorse-corner', 'door', 'The Gorse Corner', 'The last corner of the common, where the gorse has come in off the waste and taken it, dense and yellow and sharp. There is a path through it worn by animals, low down, and the bushes close over the top of it so that it is a tunnel if you are small enough.', 0, 0, 'crossing', 0, 60, 22, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorse-corner', 'west', 'the-old-hearths', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorse-corner', 'north', 'the-strand-graves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-shelf', 'east', 'the-drove-cut', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-drove-cut', 'door', 'The Drove Cut', 'The way the flocks came up, cut down into the slope by hooves and rain until it runs a body''s depth below the turf on either hand, roots and stones showing in both banks. Walking it you see nothing but sky and the two walls of earth, and nothing can see you.', 0, 0, 'mountain', 0, 88, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drove-cut', 'west', 'the-mid-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drove-cut', 'east', 'the-shiel-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drove-cut', 'south', 'the-spring-green', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-spring-green', 'door', 'The Spring Green', 'A shelf of level grass on the slope with a spring in the middle of it, walled into a stone ring and capped with a slab somebody dragged on and left crooked. The water comes up under the slab cold enough to hurt the teeth, and the bucket rope has rotted off at the windlass.', 0, 0, 'mountain', 0, 88, 12, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-green', 'north', 'the-drove-cut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-green', 'east', 'the-fold-pound', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-terrace-strips', 'door', 'The Terrace Strips', 'The slope here was cut into long level steps, each held up by a dry-stone wall, so that something could be grown on a hill that did not want it. Oats, by the look of the old stubble ridges. The walls are still standing and the strips are grass, and every one of them catches the sun all day.', 0, 0, 'mountain', 0, 89, 10, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-strips', 'south', 'the-shiel-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-strips', 'east', 'the-in-field', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-shiel-foot', 'door', 'The Shiel Foot', 'Where the strips stop and the houses start. There is no boundary except that the grass gives way to a hard rutted surface of trodden stone and the first walls stand up beside you. Somebody lit a fire against a gable end here and put it out badly, and the scorch is still black.', 0, 0, 'mountain', 0, 89, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-foot', 'north', 'the-terrace-strips', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-foot', 'west', 'the-drove-cut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-foot', 'east', 'the-shiel-street', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-foot', 'south', 'the-fold-pound', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-fold-pound', 'door', 'The Fold Pound', 'A round stone pen with a gate that still swings, built to hold sheep found straying on the hill until their owner paid to have them back. It is dry-laid and four courses high and in better repair than anything with a roof on it. Whatever was last shut in here got out over the top.', 0, 0, 'mountain', 0, 89, 12, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fold-pound', 'north', 'the-shiel-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fold-pound', 'west', 'the-spring-green', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-in-field', 'door', 'The In-Field', 'The one field near the houses that was kept and mucked and ploughed every year, while the hill above was left to the sheep. It has been neither since. What is left is a steep meadow that goes gold in the late sun, and the deer come down onto it in the evening because nothing here objects.', 0, 0, 'mountain', 0, 90, 10, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-in-field', 'west', 'the-terrace-strips', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-in-field', 'south', 'the-shiel-street', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-in-field', 'east', 'the-shiel-backs', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-shiel-street', 'door', 'The Shiel Street', 'The one street, running down the slope, wide enough for a sledge, with the shiels standing back off it behind their own low walls. The surface is stone where somebody laid stone and bare rock where the hill did. Every door in sight is shut, and that is the thing you notice and then cannot stop noticing: they were shut on the way out, by people who expected to want them shut.', 0, 0, 'mountain', 0, 90, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-street', 'west', 'the-shiel-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-street', 'north', 'the-in-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-street', 'east', 'the-hill-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-street', 'south', 'the-forge-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-forge-yard', 'door', 'The Forge Yard', 'A yard black underfoot with hammer-scale trodden into it, and it will never grow anything again. There is a stone trough at the wall, cracked through by the frost and empty, and a heap of clinker gone half to earth, and the smell of old iron still coming up out of the ground when it rains.', 0, 0, 'mountain', 0, 90, 12, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-forge-yard', 'north', 'the-shiel-street', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-forge-yard', 'south', 'the-hill-smithy', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-forge-yard', 'east', 'the-herds-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hill-smithy', 'door', 'The Hill Smithy', 'Inside, the roof holds and the light comes through the door and one wind-eye. The hearth is a stone box with a hood over it, the anvil block is still bolted down though the anvil went with somebody, and there is a wall of hooks with nothing on them. Somebody carried every piece of iron in this room up the hill on their back.', 0, 0, 'mountain', 0, 90, 13, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-smithy', 'north', 'the-forge-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-shiel-backs', 'door', 'The Shiel Backs', 'Behind the houses, the long thin plots that came with them, each walled off from the next and all of them gone to nettle and bilberry and a few gaunt rowans still berrying out of habit. There are gaps worn into the back walls where people took the short way to the field.', 0, 0, 'mountain', 0, 91, 10, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-backs', 'west', 'the-in-field', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-backs', 'south', 'the-hill-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-backs', 'east', 'the-chapel-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hill-cross', 'door', 'The Hill Cross', 'The middle of the place: a stone cross on three steps, the head broken off level and the stump worn round by the weather off the tops. People met here and were told things here, and the steps are dished where they sat. Somebody scratched a tally into the bottom step, a great many strokes, and then stopped.', 0, 0, 'mountain', 0, 91, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-cross', 'west', 'the-shiel-street', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-cross', 'north', 'the-shiel-backs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-cross', 'east', 'the-shiel-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-cross', 'south', 'the-herds-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-herds-yard', 'door', 'The Herd''s Yard', 'The biggest yard on the street, cobbled, with a byre on one side that has lost half its roof and a house on the other that has lost none of its. The herd answered for everybody else''s flocks to whoever owned the hill, which made him neither one thing nor the other, and he got a better house for it.', 0, 0, 'mountain', 0, 91, 12, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-herds-yard', 'north', 'the-hill-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-herds-yard', 'west', 'the-forge-yard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-herds-yard', 'south', 'the-herds-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-herds-yard', 'east', 'the-high-croft', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-herds-house', 'door', 'The Herd''s House', 'Two rooms and a floor above, which was wealth up here. The hearth is a proper one against a stone gable, with a lintel and a hook still in it. There is a bench built into the wall, a bedstead frame with nothing on it, and a shuttered window that still shuts. Somebody swept this floor before they left it.', 0, 0, 'mountain', 0, 91, 13, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-herds-house', 'north', 'the-herds-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-burnt-shiel', 'door', 'The Burnt Shiel', 'One shiel did burn, and only one, a long time before the rest of it emptied. The walls stand to shoulder height with the fire''s black still on the inside face, and a rowan has grown up through where the hearth was. Nobody built here again, and whatever the story was, everybody who knew it agreed about it.', 0, 0, 'mountain', 0, 92, 9, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burnt-shiel', 'south', 'the-chapel-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burnt-shiel', 'east', 'the-thorn-garth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-chapel-shelf', 'door', 'The Chapel Shelf', 'A level shelf cut into the slope in front of the chapel, kept clear of graves and used for everything else, worn bare in the middle by whatever it was used for. Two yews grow out of the wall at its edge, both enormous and both older than the chapel, standing where yews always stand.', 0, 0, 'mountain', 0, 92, 10, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-shelf', 'north', 'the-burnt-shiel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-shelf', 'west', 'the-shiel-backs', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-shelf', 'south', 'the-shiel-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-shelf', 'east', 'the-hill-chapel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-shiel-head', 'door', 'The Shiel Head', 'The street ends at a gate in a wall, and past the gate the hill falls away toward country you can see for miles. From here you can see the whole place at once, back along the length of it to the shelf, and count the roofs, and see that they are all still on.', 0, 0, 'mountain', 0, 92, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-head', 'west', 'the-hill-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-head', 'north', 'the-chapel-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-head', 'south', 'the-high-croft', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shiel-head', 'east', 'the-fleece-green', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-high-croft', 'door', 'The High Croft', 'The last yard before the wall, and the poorest: a house with a byre built onto the end of it under the same roof, so the family and the beasts lived a partition apart and kept each other warm. The muck channel still runs out through the wall and away down the hill.', 0, 0, 'mountain', 0, 92, 12, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-croft', 'north', 'the-shiel-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-croft', 'west', 'the-herds-yard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-croft', 'south', 'the-high-house', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-high-house', 'door', 'The High House', 'One room, and the byre through the gap where a partition was. The floor is beaten earth with a hearth-stone set in the middle and no chimney at all. The smoke went up through the thatch, and the underside of the thatch is black with it and hard as a shell, and that is what has kept the rain out this long.', 0, 0, 'mountain', 0, 92, 13, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-house', 'north', 'the-high-croft', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hill-chapel', 'door', 'The Hill Chapel', 'Stone, and small, and the roof is stone too, the only stone roof on this side of the hill, which is why it is the one building here that will certainly still be standing in another hundred years. Everything that could be carried was carried out. What is left is a font cut from a single block, a stone bench along the wall, and a door that shuts on the world and is thick enough to mean it.', 0, 1, 'mountain', 0, 93, 10, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-chapel', 'west', 'the-chapel-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-thorn-garth', 'door', 'The Thorn Garth', 'The chapel''s garden, walled against the sheep, and half of what grew in it is standing dead, bare grey trunks with the bark coming off in sheets, while the other half goes on fruiting out of the same thin soil for no reason anyone could explain. Windfalls rot in the grass under the living half every year, and something comes for them every night.', 0, 0, 'mountain', 0, 93, 9, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-garth', 'west', 'the-burnt-shiel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-fleece-green', 'door', 'The Fleece Green', 'Level ground with lines of low posts across it, and between the posts nothing now but the weather. Fleeces were dried here after the washing and hides were pegged out here, side by side, because the ground was common and nobody could stop either. The grass under the old lines is a different green from the rest.', 0, 0, 'mountain', 0, 93, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fleece-green', 'west', 'the-shiel-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fleece-green', 'south', 'the-lost-toft', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fleece-green', 'east', 'the-hill-spring', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-lost-toft', 'door', 'The Lost Toft', 'A house-sized rectangle of levelled ground with a low bank round it, and inside the bank not one stone standing. The walls went to somebody else''s walls and the roof went for firewood, and what is left is the shape of a home printed on the hillside. There is a doorstep, still, worn hollow.', 0, 0, 'mountain', 0, 93, 12, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lost-toft', 'north', 'the-fleece-green', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lost-toft', 'south', 'the-rowan-rows', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lost-toft', 'east', 'the-hill-graves', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rowan-rows', 'door', 'The Rowan Rows', 'Rowans planted in a row along the edge of the common, the way people up here always planted them, against whatever it is rowans are planted against. Nobody has cut them back in decades, so each has become a crooked tree with a dozen trunks, and the row is still straight underneath.', 0, 0, 'mountain', 0, 93, 13, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rowan-rows', 'north', 'the-lost-toft', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rowan-rows', 'east', 'the-scree-end', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-peat-hut', 'door', 'The Peat Hut', 'Turf walls two feet thick, a roof of turf on bent birch, no window, and a door you go through bent double. Inside it is black, smoke-black floor to roof, from a peat fire that had no chimney and did not need one. It is bone dry and warm the moment you are out of the wind, and there is old bracken bedding along one wall.', 0, 0, 'mountain', 0, 94, 10, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-peat-hut', 'south', 'the-hill-spring', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hill-spring', 'door', 'The Hill Spring', 'Not a well so much as a hole with a barrel sunk in it, where the water comes out of the hill close under the turf. The barrel staves are still sound and the water inside is clear and about three feet down and full of the sky. There is a hoof-print in the mud on every side of it.', 0, 0, 'mountain', 0, 94, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-spring', 'west', 'the-fleece-green', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-spring', 'north', 'the-peat-hut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-spring', 'south', 'the-hill-graves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-spring', 'east', 'the-cold-hearths', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hill-graves', 'door', 'The Hill Graves', 'Twenty-odd low mounds in rows, unmarked except by the grass growing greener over them, on ground outside every wall there was. When something went through here quickly they buried the dead quickly and away from everyone, which is what this is. It is a tidier piece of ground than anything else on the hill.', 0, 0, 'mountain', 0, 94, 12, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-graves', 'north', 'the-hill-spring', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-graves', 'west', 'the-lost-toft', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-graves', 'south', 'the-scree-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hill-graves', 'east', 'the-thorn-nook', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-scree-end', 'door', 'The Scree End', 'The common gives out eastward into scree and juniper and a slope of loose stone with no way across it that a person would choose. You can see a long way over the top of it and there is nothing to see: more of the same, going on down the hill until the light stops.', 0, 0, 'mountain', 0, 94, 13, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-end', 'north', 'the-hill-graves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-end', 'west', 'the-rowan-rows', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-hearths', 'door', 'The Cold Hearths', 'A ring of flat stones set in the turf, black with fire, and round them the low marks of shelters that were put up and taken down here summer after summer, before anyone built in stone. The first herders cooked here, and the stones are still the warmest thing on the hill at the end of a sunny day.', 0, 0, 'mountain', 0, 95, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-hearths', 'west', 'the-hill-spring', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-hearths', 'south', 'the-thorn-nook', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-thorn-nook', 'door', 'The Thorn Nook', 'The last corner of the common, where the thorn has come in off the hill and taken it, dense and low and sharp. There is a path through it worn by animals, low down, and the bushes close over the top of it so that it is a tunnel if you are small enough.', 0, 0, 'mountain', 0, 95, 12, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-nook', 'north', 'the-cold-hearths', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-nook', 'west', 'the-hill-graves', NULL);
